// All figures shown on the site come from these files, generated by
// `uv run python -m voldrag.export_web` from the committed results/.
import performanceJson from "../../public/data/performance.json";
import curvesPrimaryJson from "../../public/data/curves_primary.json";
import curvesSecondaryJson from "../../public/data/curves_secondary.json";
import crisisJson from "../../public/data/crisis_2020.json";
import dragJson from "../../public/data/drag.json";
import provenanceJson from "../../public/data/provenance.json";
import submissionJson from "../../public/data/submission_simulation.json";

export type StrategyId = "6040" | "ew" | "mvo" | "ito_hist" | "ito_tsfm" | "proposed";
export type PeriodId = "primary" | "secondary";

export interface Source { file: string; commit: string; sha256: string }

export interface Perf {
  years: number; cagr_pct: number; mu_arith_pct: number; sigma_pct: number; sharpe: number;
  sortino: number; mdd_pct: number; calmar: number; cvar95_daily_pct: number;
  turnover_annual_pct: number; emp_drag_pct: number; theo_drag_pct: number; wealth_loss_10y: number;
}

export interface Bootstrap { sharpe_diff: number; p_value: number; ci95: [number, number]; block: number; n_boot: number }

export interface Safeguard { days_beta_positive: number; first_trigger: string | null; max_beta: number; mean_cash_weight_pct: number }
export type Episode = Record<StrategyId, { return_pct: number; mdd_pct: number }> & { proposed_safeguard: Safeguard };

export interface Performance {
  labels: Record<StrategyId, string>;
  periods: Record<PeriodId, { start: string; end: string }>;
  costs_bp: number[];
  base_cost_bp: number;
  performance: Record<PeriodId, Record<string, Record<StrategyId, Perf>>>;
  bootstrap: Record<PeriodId, Bootstrap>;
  episodes: Record<string, Episode>;
  episode_windows: Record<string, { start: string; end: string }>;
  source: Source;
  exploratory_costs: { label: string; costs_bp: number[]; performance: Record<PeriodId, Record<string, Record<StrategyId, Perf>>>; source: Source };
}

export type CurveRow = { date: string } & Record<StrategyId, number>;
export interface Curves { period: PeriodId; start: string; end: string; resample: string; cost_bp: number; strategies: StrategyId[]; rows: CurveRow[]; source: Source }

export type CrisisRow = CurveRow & { beta: number; score: number; tau: number; cash_weight: number };
export interface Crisis {
  window: { start: string; end: string };
  cost_bp: number;
  strategies: StrategyId[];
  rows: CrisisRow[];
  episode: Episode;
  episode_window: { start: string; end: string };
  submission_narrative: { trigger_date: string; cash_pct: number; mdd_pct: number; nature: string; source: Source };
  sources: Record<"daily_returns" | "safeguard_signals" | "weights" | "episodes", Source>;
  weights_note: string;
}

export interface Drag { cost_bp: number; drag: Record<PeriodId, Record<StrategyId, { emp_drag_pct: number; theo_drag_pct: number; sigma_pct: number }>>; source: Source }

export interface Commit { sha: string; short: string; date: string; subject: string }
export interface Provenance {
  repo: string;
  submission_repo: string;
  timeline: Record<"preregistration" | "code" | "results" | "weights_export", Commit>;
  head: Commit;
  amendments: { title: string; summary: string; details: string[] }[];
  data_reference_tests: { command: string; passed: number; failed: number; total: number; summary: string; ran_at: string };
  submission: { repo: string; path: string; commit: string; commit_date: string; sha256: string };
  run_command: string;
  reproduction_report: string;
}

type SubStrategy = "benchmark_6040" | "equal_weight" | "mvo" | "proposed";
export interface Submission {
  metadata: { nature: string; disclosure_ko: string; source_commit: string; sample: { start: string; end: string; trading_days: number }; known_caveats: string[] };
  labels: Record<string, { ko: string; en: string }>;
  strategies: Record<SubStrategy, {
    name: string;
    parameters: { mu_arith_pct: number; sigma_pct: number; mdd_pct: number };
    analytic: { cagr_pct: number; sharpe: number; theo_drag_pct: number; loss_10y_eok: number };
  }>;
  monte_carlo: {
    n_paths: number; years: number; seed: number;
    strategies: Record<SubStrategy, { name: string; wealth_10y: { unit: string; mean: number; median: number; p05: number; p95: number } }>;
  };
  illustrative_scenario: { cost_sensitivity: ({ cost_bp: number; label: string } & Record<SubStrategy, { cagr_pct: number; sharpe: number }>)[] };
}

export const performance = performanceJson as unknown as Performance;
export const curves: Record<PeriodId, Curves> = {
  primary: curvesPrimaryJson as unknown as Curves,
  secondary: curvesSecondaryJson as unknown as Curves,
};
export const crisis = crisisJson as unknown as Crisis;
export const drag = dragJson as unknown as Drag;
export const provenance = provenanceJson as unknown as Provenance;
export const submission = submissionJson as unknown as Submission;

export const STRATEGIES: StrategyId[] = ["6040", "ew", "mvo", "ito_hist", "ito_tsfm", "proposed"];
export const SUB_KEY: Partial<Record<StrategyId, SubStrategy>> = {
  "6040": "benchmark_6040", ew: "equal_weight", mvo: "mvo", proposed: "proposed",
};

export const PERIOD_LABEL: Record<PeriodId, string> = {
  primary: "1차 평가 (완전 표본 외)",
  secondary: "2차 평가 (제출본과 같은 기간)",
};

// Korean display names for the strategies (labels in performance.json are English).
export const KO: Record<StrategyId, string> = {
  "6040": "전통 60/40",
  ew: "동일가중 1/N",
  mvo: "MVO (최대 샤프)",
  ito_hist: "이토-켈리 · 과거 모멘트",
  ito_tsfm: "이토-켈리 · Chronos",
  proposed: "제안 모델 (+ 세이프가드)",
};

// ---------- formatting ----------
export const fmt = (v: number, d = 2) => v.toLocaleString("ko-KR", { minimumFractionDigits: d, maximumFractionDigits: d });
export const pct = (v: number, d = 2) => `${fmt(v, d)}%`;
export const signed = (v: number, d = 2) => `${v > 0 ? "+" : v < 0 ? "−" : "±"}${fmt(Math.abs(v), d)}`;
export const dateKo = (iso: string) => {
  const [y, m, d] = iso.slice(0, 10).split("-").map(Number);
  return `${y}년 ${m}월 ${d}일`;
};
export const shortDate = (iso: string) => {
  const [, m, d] = iso.slice(0, 10).split("-").map(Number);
  return `${m}/${d}`;
};
export const dateTimeKo = (iso: string) => {
  const t = new Date(iso);
  return t.toLocaleString("ko-KR", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false });
};
